source(file.path("r", "feature_prepartita.R"))

date <- as.Date(c("2026-01-01", "2026-01-02", "2026-01-03", "2026-01-04", "2026-01-05", "2026-01-06", "2026-01-10"))
giocatori <- data.frame(idPlayer = c(rep("p1", 7), rep("p2", 6)), dateGame = c(date, date[1:6]), idGame = as.character(seq_len(13)), yearSeason = 2026L, slugTeam = "AAA", slugOpponent = "BBB", namePlayer = c(rep("Confermato", 7), rep("Bloccato", 6)), minutes = c(10, 11, 12, 13, 14, 15, 999, rep(20, 6)), pts = c(1, 2, 3, 4, 5, 6, 999, rep(7, 6)), ast = 1, treb = 2, fga = 1, fta = 1, tov = 1, oreb = 1, dreb = 1, fgm = 1, fg2m = 1, fg2a = 1, ftm = 1)
squadre <- do.call(rbind, lapply(seq_len(6), function(i) data.frame(idGame = paste0("t", i), dateGame = date[i], slugTeam = c("AAA", "BBB"), slugOpponent = c("BBB", "AAA"), yearSeason = 2026L, ptsTeam = c(100 + i, 90 + i), fgaTeam = 80, ftaTeam = 20, tovTeam = 10, orebTeam = 8, astTeam = 20, trebTeam = 40, drebTeam = 30)))
mappa <- data.frame(sigla = c("AAA", "AAA", "AAA"), nome_giocatore = c("Confermato", "Bloccato", "Nuovo Rookie"), idPlayer = c("p1", "p2", "p3"), esito = c("confermato", "ambiguo_roster", "confermato_nba"))
calendario <- data.frame(id_partita = "f1", dateGame = as.Date("2026-01-10"), sigla = "AAA", sigla_avversaria = "BBB")
risultato <- costruisci_feature_prepartita(giocatori, squadre, calendario, mappa)
stopifnot(nrow(risultato) == 2L, risultato$minutes_season_avg[risultato$idPlayer == "p1"] == 12.5, risultato$pts_L1[risultato$idPlayer == "p1"] == 6, risultato$pts_H2H_L3[risultato$idPlayer == "p1"] == 5, risultato$ptsOpp_season_avg[risultato$idPlayer == "p1"] == 103.5)
stopifnot(!any(risultato$idPlayer == "p2"), all(risultato$dateGame == as.Date("2026-01-10")), !risultato$storico_disponibile[risultato$idPlayer == "p3"], !risultato$eligible_modello_storico[risultato$idPlayer == "p3"])
destinazione <- tempfile(fileext = ".csv")
scrivi_feature_prepartita_atomico(risultato, destinazione)
stopifnot(file.exists(destinazione), nrow(utils::read.csv(destinazione, stringsAsFactors = FALSE)) == 2L)
cat("test_feature_prepartita: OK\n")
